from pathlib import Path
import json,hashlib,stat,sqlite3,sys
out=Path(__file__).resolve().parent;f=json.loads((out/'fixture.json').read_text());root=Path(f['workspace_root']);snap={str(p.relative_to(root)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in root.rglob('*') if p.is_file()};assert snap==json.loads((out/'repository-before.json').read_text());before=json.loads((out/'records-before.json').read_text());c=sqlite3.connect('file:'+f['state']+'/state.db?mode=ro',uri=True);ops=dict(c.execute('select id,payload from write_operations'));batches=dict(c.execute("select key,value from state where key like 'batch:%'"));assert all(ops[k]==v for k,v in before['operations'].items()) and all(batches[k]==v for k,v in before['batches'].items());new=[json.loads(v) for k,v in ops.items() if k not in before['operations']];assert len(new)==1 and not new[0]['published'] and new[0]['phase']=='cancelled_before_publication';newb=[json.loads(v) for k,v in batches.items() if k not in before['batches']];assert len(newb)==1 and newb[0]['phase']=='cancelled';assert c.execute('pragma integrity_check').fetchone()[0]=='ok';assert set(c.execute('select worktree_id,revoked from write_trust').fetchall())=={(f['entries'][f['parent']],0),(f['entries'][f['child']],0)};result={'repository_exact_bytes_modes_preserved':True,'prior_operations_batches_unchanged':True,'one_cancelled_proposal_only':True,'no_application_publication':True,'exact_original_two_trusts':True,'sqlite_integrity':'ok'};(out/('verify-'+sys.argv[1]+'.json')).write_text(json.dumps(result,indent=2)+'\n');print(result)
